use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let input_str = input.to_string();
    let digits = input_str.chars().filter(|c| c.is_digit(10)).collect::<Vec<char>>();
    let sum = digits.iter().enumerate().map(|(i, &d)| (d - '0') * (10 - i)).sum::<i64>();
    let checksum = sum % 10;
    let is_valid = checksum == 0 || (checksum % 10 == 5 && digits.len() == 11);
    serde_json::Value::Bool(is_valid)
}
